59	        isClosingRef.current = false;
60	        onClose();
61	      });
62	    }, [fadeIn, onClose]);
63	
64	    useImperativeHandle(ref, () => ({
65	      close: () => {
66	        handleDismiss();
67	        sheetRef.current?.dismiss();
68	      },
69	    }));
70	
71	    usePreventSwipeBack(isOpen);
72	
73	    useEffect(() => {
74	      if (!isOpen) return;
