95	          backgroundStyle={styles.background}
96	          enablePanDownToClose
97	          enableDynamicSizing
98	          maxDynamicContentSize={maxContentSize ?? height - 200}
99	          onDismiss={handleDismiss}
100	          enableContentPanningGesture={enableContentPanningGesture}
101	          keyboardBehavior={keyboardBehavior}
102	          keyboardBlurBehavior={keyboardBlurBehavior}
103	          android_keyboardInputMode={android_keyboardInputMode}
104	        >
105	          {children}
106	        </BottomSheetModal>
107	      </Block>
108	    );
109	  },
110	);
111	
112	const styles = StyleSheet.create({
113	  background: {
114	    backgroundColor: Colors.blackMinus1,
115	    borderTopLeftRadius: 24,
116	    borderTopRightRadius: 24,
117	  },
118	  handle: {
119	    borderWidth: 1,
120	    borderBottomWidth: 0,
121	    borderTopLeftRadius: 24,
122	    borderTopRightRadius: 24,
