120	  public static forwardMessage = async (
121	    roomId: string,
122	    event: EventTimelineItem,
123	    messageType: ForwardMessageType,
124	  ) => {
125	    const client = MatrixCore.getClient();
126	    const room = MatrixCore.getRoom(roomId);
127	    const timeline = await room.timeline();
128	    if (!timeline) throw new Error("Timeline not found");
129	
130	    if (messageType === "text") {
131	      const textContent = this.getTextContent(event);
132	      if (!textContent) throw new Error("Text content not found");
133	      await timeline.send(messageEventContentFromMarkdown(textContent));
134	      return;
135	    }
136	
137	    if (messageType === "image") {
138	      const imageContent = this.getImageContent(event);
139	      if (!imageContent) throw new Error("Image content not found");
140	
141	      const mediaFile = await client.getMediaFile(
142	        imageContent.source,
143	        imageContent.filename,
144	        imageContent.info?.mimetype || "image/jpeg",
145	        true,
146	        undefined,
147	      );
148	      const filePath = mediaFile.path();
149	      const fileSource: UploadParameters = {
150	        source: new UploadSource.File({ filename: filePath }),
151	        caption: imageContent.caption || undefined,
152	        formattedCaption: undefined,
153	        mentions: undefined,
154	        inReplyTo: undefined,
155	      };
156	      const imageHandle = timeline.sendImage(
157	        fileSource,
158	        new UploadSource.File({ filename: filePath }),
159	        {
160	          height: imageContent.info?.height || BigInt(0),
161	          width: imageContent.info?.width || BigInt(0),
162	          mimetype: imageContent.info?.mimetype || "image/jpeg",
163	          size: imageContent.info?.size || BigInt(0),
164	          thumbnailInfo: imageContent.info?.thumbnailInfo,
165	          thumbnailSource: undefined,
166	          blurhash: imageContent.info?.blurhash || "",
167	          isAnimated: false,
168	        },
169	      );
170	      await imageHandle.join();
171	      return;
172	    }
173	
174	    if (messageType === "video") {
175	      const videoContent = this.getVideoContent(event);
176	      if (!videoContent) throw new Error("Video content not found");
177	
178	      const mediaFile = await client.getMediaFile(
179	        videoContent.source,
180	        videoContent.filename,
181	        videoContent.info?.mimetype || "video/mp4",
182	        true,
183	        undefined,
184	      );
185	      const filePath = mediaFile.path();
186	      const fileSource: UploadParameters = {
187	        source: new UploadSource.File({ filename: filePath }),
188	        caption: videoContent.caption || undefined,
189	        formattedCaption: undefined,
190	        mentions: undefined,
191	        inReplyTo: undefined,
192	      };
193	      const videoHandle = timeline.sendVideo(
194	        fileSource,
195	        new UploadSource.File({ filename: filePath }),
196	        {
197	          height: videoContent.info?.height || BigInt(0),
198	          width: videoContent.info?.width || BigInt(0),
199	          mimetype: videoContent.info?.mimetype || "video/mp4",
200	          size: videoContent.info?.size || BigInt(0),
201	          duration: videoContent.info?.duration || 0,
202	          thumbnailInfo: videoContent.info?.thumbnailInfo,
203	          thumbnailSource: undefined,
204	          blurhash: videoContent.info?.blurhash || "",
205	        },
206	      );
207	      await videoHandle.join();
208	      return;
209	    }
210	
211	    if (messageType === "audio") {
212	      const audioContent = this.getAudioContent(event);
213	      if (!audioContent) throw new Error("Audio content not found");
214	
215	      const mediaFile = await client.getMediaFile(
216	        audioContent.source,
217	        audioContent.filename,
218	        audioContent.info?.mimetype || "audio/mpeg",
219	        true,
220	        undefined,
221	      );
222	      const filePath = mediaFile.path();
223	      const fileSource: UploadParameters = {
224	        source: new UploadSource.File({ filename: filePath }),
225	        caption: undefined,
226	        formattedCaption: undefined,
227	        mentions: undefined,
228	        inReplyTo: undefined,
229	      };
230	      const audioHandle = timeline.sendAudio(fileSource, {
231	        mimetype: audioContent.info?.mimetype || "audio/mpeg",
232	        size: audioContent.info?.size || BigInt(0),
233	        duration: audioContent.info?.duration || 0,
234	      });
235	      await audioHandle.join();
236	      return;
237	    }
238	
239	    if (messageType === "file") {
240	      const fileContent = this.getFileContent(event);
241	      if (!fileContent) throw new Error("File content not found");
242	
243	      const mediaFile = await client.getMediaFile(
244	        fileContent.source,
245	        fileContent.filename,
246	        fileContent.info?.mimetype || "application/octet-stream",
247	        true,
248	        undefined,
249	      );
250	      const filePath = mediaFile.path();
251	      const fileHandle = timeline.sendFile(
252	        {
253	          source: new UploadSource.File({ filename: filePath }),
254	          caption: undefined,
255	          formattedCaption: undefined,
256	          mentions: undefined,
257	          inReplyTo: undefined,
258	        },
259	        {
260	          size: fileContent.info?.size || BigInt(0),
261	          mimetype: fileContent.info?.mimetype || "application/octet-stream",
262	          thumbnailInfo: undefined,
263	          thumbnailSource: undefined,
264	        },
265	      );
266	      await fileHandle.join();
267	      return;
268	    }
269	
270	    throw new Error(`Unsupported message type: ${messageType}`);
271	  };
