478	
479	  private static getReceiptTimestamp = (receipt: unknown): number | null => {
480	    if (typeof receipt === "number") return receipt;
481	    if (typeof receipt === "bigint") return Number(receipt);
482	    if (!receipt || typeof receipt !== "object") return null;
483	
484	    const maybeReceipt = receipt as Record<string, unknown>;
485	    const candidate =
486	      maybeReceipt.ts ??
487	      maybeReceipt.timestamp ??
488	      maybeReceipt.originServerTs ??
489	      maybeReceipt.origin_server_ts;
490	
491	    if (typeof candidate === "number") return candidate;
492	    if (typeof candidate === "bigint") return Number(candidate);
493	    if (typeof candidate === "string") {
494	      const parsed = Number(candidate);
495	      return Number.isFinite(parsed) ? parsed : null;
496	    }
497	
498	    return null;
499	  };
