501	  private static getTextContent = (event: EventTimelineItem): string | null => {
502	    if (event.content.tag === TimelineItemContent_Tags.MsgLike) {
503	      const kind = event.content.inner.content.kind;
504	      if (kind?.tag === MsgLikeKind_Tags.Message) {
505	        return kind.inner.content.body;
506	      }
507	    }
508	    return null;
509	  };
