511	  private static getImageContent = (
512	    event: EventTimelineItem,
513	  ): ImageMessageContent | null => {
514	    if (event.content.tag === TimelineItemContent_Tags.MsgLike) {
515	      const kind = event.content.inner.content.kind;
516	      if (kind?.tag === MsgLikeKind_Tags.Message) {
517	        const msgType = kind.inner.content.msgType;
518	        if (msgType?.tag === MessageType_Tags.Image) {
519	          return msgType.inner.content;
520	        }
521	      }
522	    }
523	    return null;
524	  };
