2	import type { NativeStackScreenProps } from "@react-navigation/native-stack";
3	import { useAtomValue, useSetAtom } from "jotai";
4	import { StorageAtoms } from "modules/storage/jotai/atoms";
5	import { TimelineAtoms } from "modules/timeline/jotai/atoms";
6	import { UserService } from "modules/user/service/UserService";
7	import { useState } from "react";
8	import { ActivityIndicator, Image, Modal, StyleSheet } from "react-native";
9	import type { Asset } from "react-native-image-picker";
