22	import { offlineToastHelper } from "shared/utils";
23	
24	export const UserProfile: React.FC<
25	  NativeStackScreenProps<Routes, "userProfile">
26	> = () => {
27	  const user = useAtomValue(StorageAtoms.cachedProfile);
28	  const [userImageUri, setUserImageUri] = useState<string | undefined>(
29	    user?.avatarUrl,
30	  );
31	  const {
32	    isLoading,
33	    selectedAsset,
34	    isListOpen,
35	    setSelectedAsset,
36	    setIsListOpen,
37	    handleChoosePhoto,
38	    handleTakePhoto,
39	  } = useUploadPhoto();
40	  const [displayName, setDisplayName] = useState<string | undefined>(
41	    user?.displayName,
42	  );
43	  const [isSaving, setIsSaving] = useState(false);
44	  const [shouldRemoveAvatar, setShouldRemoveAvatar] = useState(false);
45	  const setImageViewerUri = useSetAtom(TimelineAtoms.imageViewerUri);
46	
47	  const handleRemove = () => {
48	    setUserImageUri(undefined);
49	    setSelectedAsset(null);
50	    setShouldRemoveAvatar(true);
51	  };
52	
53	  const handleSave = async () => {
54	    try {
55	      setIsSaving(true);
56	
57	      let avatarToUpload: Asset | null | undefined;
58	
59	      if (shouldRemoveAvatar) {
60	        avatarToUpload = null; // User wants to remove avatar
61	      } else if (selectedAsset) avatarToUpload = selectedAsset;
62	
63	      const updated = await UserService.updateProfile(
64	        displayName,
65	        avatarToUpload,
66	      );
67	
68	      setShouldRemoveAvatar(false);
69	      setSelectedAsset(null);
70	
71	      // The user state will be automatically updated via the atom
72	      setUserImageUri(updated?.avatarUrl);
73	      setDisplayName(updated?.displayName);
74	
75	      Toast.show({
76	        type: "success",
77	        text1: "Profile updated successfully",
78	      });
79	    } catch (error) {
80	      console.error("Failed to update profile:", error);
81	      offlineToastHelper("Failed to update profile. Please try again.");
82	    } finally {
83	      setIsSaving(false);
84	    }
85	  };
86	
87	  const rightComponent = () => {
88	    const shouldShow =
89	      shouldRemoveAvatar || selectedAsset || displayName !== user?.displayName;
90	
91	    if (!shouldShow) return null;
92	
93	    return (
94	      <Button.Wrapper onPress={handleSave} disabled={isSaving}>
95	        <Text>{isSaving ? "Saving..." : "Save"}</Text>
96	      </Button.Wrapper>
97	    );
98	  };
99	
100	  return (
101	    <ScreenLayout paddings={{ paddingHorizontal: 16 }}>
102	      {isSaving && <Loading text="Saving..." />}
103	      <Block align="center">
104	        <GoBackHeader
105	          margins={{ marginBottom: 40 }}
106	          title="Profile"
107	          rightComp={rightComponent()}
108	        />
