1	import { Block, Text } from "@prototyp/skeletor";
2	import {
3	  type EventTimelineItem,
4	  type FileMessageContent,
5	  MessageType_Tags,
6	  MsgLikeKind_Tags,
7	  TimelineItemContent_Tags,
8	} from "@unomed/react-native-matrix-sdk";
9	import { MatrixCore } from "modules/matrix-client/services/MatrixCore";
10	import { getEventId, getEventTextContent } from "modules/matrix-client/utils";
11	import { NavigationContainerRef } from "modules/navigation/const";
12	import { TimelineService } from "modules/timeline/service/TimelineService";
13	import type { FC } from "react";
14	import { useState } from "react";
15	import { Dimensions, Image, Share } from "react-native";
16	import {
17	  Button,
18	  Loading,
19	  MessageTimestamp,
20	  PinIndicator,
21	  SeenBy,
22	} from "shared/components";
23	import { Colors, TextSize } from "shared/styles";
24	import {
25	  copyToStablePath,
26	  formatBytes,
27	  isPdf,
28	  offlineToastHelper,
29	} from "shared/utils";
30	import { MessageLongPressWrapper } from "../message-long-press-wrapper";
31	import { MessageSender } from "../message-sender";
32	
33	interface Props {
34	  event: EventTimelineItem;
35	  isPreviousSameSender: boolean;
36	  onMemberPress?: (member: MemberDetailsPayload) => void;
37	}
38	
39	const getFileContent = (
40	  event: EventTimelineItem,
41	): FileMessageContent | null => {
42	  if (event.content.tag === TimelineItemContent_Tags.MsgLike) {
43	    const kind = event.content.inner.content.kind;
44	    if (kind?.tag === MsgLikeKind_Tags.Message) {
45	      const msgType = kind.inner.content.msgType;
46	      if (msgType?.tag === MessageType_Tags.File) return msgType.inner.content;
47	    }
48	  }
49	  return null;
50	};
51	
52	const { width } = Dimensions.get("window");
53	
54	export const FileMessage: FC<Props> = ({
55	  event,
56	  isPreviousSameSender,
57	  onMemberPress,
58	}) => {
59	  const content = getFileContent(event);
60	  const eventId = getEventId(event);
61	  const [messageWidth, setMessageWidth] = useState(40);
62	  const [isDownloading, setIsDownloading] = useState(false);
63	  const isUser = event.isOwn;
64	  const sender = event.senderProfile;
65	  const senderId = event.sender;
66	  const maxWidth = width - 60;
67	  const seenByUsers = TimelineService.getReadReceiptUsers(event);
68	
69	  const handleOpen = async () => {
70	    if (!content?.source || !MatrixCore.instance) return;
71	
72	    try {
73	      setIsDownloading(true);
74	
75	      const ext =
76	        content.info?.mimetype?.split("/")[1] ??
77	        content.filename?.split(".").pop() ??
78	        "bin";
79	      const filename = content.filename ?? `file-${eventId}.${ext}`;
80	
81	      const mediaHandle = await MatrixCore.instance.getMediaFile(
82	        content.source,
83	        filename,
84	        content.info?.mimetype || "application/octet-stream",
85	        false,
86	        undefined,
87	      );
88	
89	      const filePath = mediaHandle.path();
90	
91	      if (isPdf(content)) {
92	        const stableUrl = await copyToStablePath(filePath, filename);
93	        NavigationContainerRef.navigate("pdfViewer", {
94	          fileUrl: stableUrl,
95	          filename,
96	        });
97	        return;
98	      }
99	
100	      const fileUrl = filePath.startsWith("file://")
101	        ? filePath
102	        : `file://${filePath}`;
103	      await Share.share({ url: fileUrl });
104	    } catch {
105	      offlineToastHelper("Failed to open file");
106	    } finally {
107	      setIsDownloading(false);
108	    }
109	  };
110	
111	  if (!content) return null;
112	
113	  return (
114	    <Block
115	      align={isUser ? "flex-end" : "flex-start"}
116	      margins={{ marginTop: isPreviousSameSender ? 6 : 16 }}
117	    >
118	      <MessageSender
119	        sender={sender}
120	        isUser={isUser}
121	        senderId={senderId}
122	        isPreviousSameSender={isPreviousSameSender}
123	        onMemberPress={onMemberPress}
124	      />
125	      <MessageLongPressWrapper
126	        event={event}
127	        content={getEventTextContent(event)}
128	      >
129	        <Block flexDirection={isUser ? "row-reverse" : "row"}>
130	          <Block
131	            paddings={12}
132	            background={isUser ? Colors.primary : Colors.message}
133	            border={{ borderRadius: 16 }}
134	            flexDirection={isUser ? "row-reverse" : "row"}
135	            gap={12}
136	            align="center"
137	            maxWidth={maxWidth}
138	            onLayout={(e) => setMessageWidth(e.nativeEvent.layout.width)}
139	          >
140	            <Button.Wrapper disabled={isDownloading} onPress={handleOpen}>
141	              <Block
142	                width={40}
143	                height={40}
144	                align="center"
145	                justify="center"
146	                background={Colors.white20}
147	                border={{ borderRadius: 20 }}
148	              >
149	                {isDownloading ? (
150	                  <Loading isFullScreen={false} />
151	                ) : (
152	                  <Image
153	                    source={require("assets/icons/download.png")}
154	                    style={{ width: 20, height: 20 }}
155	                    tintColor={Colors.white}
156	                  />
157	                )}
158	              </Block>
159	            </Button.Wrapper>
160	            <Block gap={2} flex={{ flexShrink: 1 }} minWidth={0}>
161	              <Text size={TextSize.small} color="white" numberOfLines={1}>
162	                {content.filename ?? "File"}
163	              </Text>
164	              {content.info?.size != null && (
165	                <Text
166	                  size={TextSize.tiny}
167	                  color={Colors.white50}
168	                  numberOfLines={1}
169	                >
170	                  {formatBytes(content.info.size)}
171	                </Text>
172	              )}
173	            </Block>
174	            <MessageTimestamp event={event} isUser={isUser} />
175	          </Block>
176	          <PinIndicator event={event} />
177	        </Block>
178	      </MessageLongPressWrapper>
179	      <SeenBy users={seenByUsers} messageWidth={messageWidth} isUser={isUser} />
180	    </Block>
181	  );
182	};
183

