          ) : localUri ? (
            <ImageZoom
              key={localUri}
              uri={localUri}
              minScale={1}
              maxScale={5}
              maxPanPointers={2}
              isPanEnabled
              isPinchEnabled
              isDoubleTapEnabled
              isSingleTapEnabled
              style={styles.image}
              onLoad={handleImageLoad}
              onError={handleImageError}
              onSingleTap={handleSingleTap}
            />
          ) : null}
          </Block>
        </Block>
        <ImageInfoBottomSheet />
      </BottomSheetModalProvider>
    </Modal>
  );
};

