import type { FileMessageContent } from "@unomed/react-native-matrix-sdk";
import ReactNativeBlobUtil from "react-native-blob-util";

export const formatBytes = (bytes: bigint | number | null | undefined) => {
  if (bytes == null) return "";
  const n = Number(bytes);
  if (n < 1024) return `${n} B`;
  if (n < 1024 * 1024) return `${(n / 1024).toFixed(1)} KB`;
  return `${(n / (1024 * 1024)).toFixed(1)} MB`;
};

export const isPdf = (content: FileMessageContent) =>
  content.info?.mimetype === "application/pdf" ||
  content.filename?.toLowerCase().endsWith(".pdf");

export async function copyToStablePath(
  filePath: string,
  filename: string,
): Promise<string> {
  const prefixlessPath = filePath.startsWith("file://")
    ? filePath.slice(7)
    : filePath;
  const pdfCacheDir = `${ReactNativeBlobUtil.fs.dirs.CacheDir.replace("file://", "")}/pdfs`;
  if (!(await ReactNativeBlobUtil.fs.exists(pdfCacheDir))) {
    await ReactNativeBlobUtil.fs.mkdir(pdfCacheDir);
  }
  const stablePath = `${pdfCacheDir}/${filename}`;
  if (await ReactNativeBlobUtil.fs.exists(stablePath)) {
    await ReactNativeBlobUtil.fs.unlink(stablePath);
  }
  await ReactNativeBlobUtil.fs.cp(prefixlessPath, stablePath);
  return `file://${stablePath}`;
}

